function Magnetometer = GenerateIdealMagnetometer(GroundTruth, Timeline)
%GENERATEIDEALMAGNETOMETER Generate ideal body-frame magnetometer data.
%
%   Magnetometer = GenerateIdealMagnetometer(GroundTruth, Timeline)
%
%   Inputs
%   ------
%   GroundTruth : struct
%       Ground-truth telemetry generated by:
%           groundtruthtelemetry.ConvertGroundTruthState
%
%       Required fields:
%           GroundTruth.Time_s
%           GroundTruth.Position.Latitude_rad
%           GroundTruth.Position.Longitude_rad
%           GroundTruth.Position.Altitude_m
%           GroundTruth.Euler_rad
%
%   Timeline : struct
%       Magnetometer sensor timeline generated by:
%           sensormodels.BuildSensorTimeline
%
%       Required fields:
%           Timeline.Time_s
%           Timeline.SampleRate_Hz
%           Timeline.SampleCount
%
%   Outputs
%   -------
%   Magnetometer : struct
%       Magnetometer telemetry containing:
%           Magnetometer.Time_s
%           Magnetometer.SampleRate_Hz
%           Magnetometer.SampleCount
%           Magnetometer.MagneticFieldBody_uT
%           Magnetometer.Available
%
%   Model
%   -----
%   The World Magnetic Model is evaluated at each ground-truth
%   position. MATLAB Aerospace Toolbox returns the magnetic field
%   components in NED coordinates in nT.
%
%   The field is then transformed from NED to BODY using the existing
%   Block 2 Euler/quaternion/DCM functions:
%
%       B_body = Cbn' * B_NED
%
%   The magnetic field is converted from nT to uT.
%
%   No magnetic-field data is added to GroundTruth.

    %% Input validation

    RequiredGroundTruthFields = { ...
        'Time_s', ...
        'Position', ...
        'Euler_rad'};

    for FieldIndex = 1:numel(RequiredGroundTruthFields)

        FieldName = RequiredGroundTruthFields{FieldIndex};

        if ~isfield(GroundTruth, FieldName)

            error( ...
                'sensormodels:GenerateIdealMagnetometer:MissingGroundTruthField', ...
                'GroundTruth.%s is required.', ...
                FieldName);
        end
    end

    RequiredPositionFields = { ...
        'Latitude_rad', ...
        'Longitude_rad', ...
        'Altitude_m'};

    for FieldIndex = 1:numel(RequiredPositionFields)

        FieldName = RequiredPositionFields{FieldIndex};

        if ~isfield(GroundTruth.Position, FieldName)

            error( ...
                'sensormodels:GenerateIdealMagnetometer:MissingPositionField', ...
                'GroundTruth.Position.%s is required.', ...
                FieldName);
        end
    end

    RequiredTimelineFields = { ...
        'Time_s', ...
        'SampleRate_Hz', ...
        'SampleCount'};

    for FieldIndex = 1:numel(RequiredTimelineFields)

        FieldName = RequiredTimelineFields{FieldIndex};

        if ~isfield(Timeline, FieldName)

            error( ...
                'sensormodels:GenerateIdealMagnetometer:MissingTimelineField', ...
                'Timeline.%s is required.', ...
                FieldName);
        end
    end

    %% Extract GroundTruth

    GroundTruthTime_s = GroundTruth.Time_s(:);

    Latitude_rad = ...
        GroundTruth.Position.Latitude_rad(:);

    Longitude_rad = ...
        GroundTruth.Position.Longitude_rad(:);

    Altitude_m = ...
        GroundTruth.Position.Altitude_m(:);

    Euler_rad = GroundTruth.Euler_rad;

    GroundTruthSampleCount = numel(GroundTruthTime_s);

    %% Validate GroundTruth dimensions

    if numel(Latitude_rad) ~= GroundTruthSampleCount

        error( ...
            'sensormodels:GenerateIdealMagnetometer:LatitudeSizeMismatch', ...
            ['GroundTruth.Position.Latitude_rad must have one ' ...
             'value per GroundTruth.Time_s sample.']);
    end

    if numel(Longitude_rad) ~= GroundTruthSampleCount

        error( ...
            'sensormodels:GenerateIdealMagnetometer:LongitudeSizeMismatch', ...
            ['GroundTruth.Position.Longitude_rad must have one ' ...
             'value per GroundTruth.Time_s sample.']);
    end

    if numel(Altitude_m) ~= GroundTruthSampleCount

        error( ...
            'sensormodels:GenerateIdealMagnetometer:AltitudeSizeMismatch', ...
            ['GroundTruth.Position.Altitude_m must have one ' ...
             'value per GroundTruth.Time_s sample.']);
    end

    if size(Euler_rad,1) ~= GroundTruthSampleCount || ...
            size(Euler_rad,2) ~= 3

        error( ...
            'sensormodels:GenerateIdealMagnetometer:InvalidEulerSize', ...
            'GroundTruth.Euler_rad must be N-by-3.');
    end

    %% Extract sensor timeline

    SensorTime_s = Timeline.Time_s(:);
    SensorSampleCount = Timeline.SampleCount;

    if numel(SensorTime_s) ~= SensorSampleCount

        error( ...
            'sensormodels:GenerateIdealMagnetometer:TimelineSizeMismatch', ...
            'Timeline.SampleCount must match Timeline.Time_s.');
    end

    %% Interpolate position and attitude onto sensor timeline

    LatitudeSensor_rad = interp1( ...
        GroundTruthTime_s, ...
        Latitude_rad, ...
        SensorTime_s, ...
        'linear');

    LongitudeSensor_rad = interp1( ...
        GroundTruthTime_s, ...
        Longitude_rad, ...
        SensorTime_s, ...
        'linear');

    AltitudeSensor_m = interp1( ...
        GroundTruthTime_s, ...
        Altitude_m, ...
        SensorTime_s, ...
        'linear');

    EulerSensor_rad = interp1( ...
        GroundTruthTime_s, ...
        Euler_rad, ...
        SensorTime_s, ...
        'linear');

    %% Magnetic field model configuration
    %
    % The Aerospace Toolbox World Magnetic Model requires decimal year.
    %
    % No scenario date is present in the frozen Block 7 GroundTruth
    % interface, therefore the model epoch is explicitly fixed here for
    % deterministic project operation.

    MagneticModelYear = 2024;

    %% Generate ideal magnetic-field measurements

    MagneticFieldBody_uT = zeros(SensorSampleCount,3);

    for SampleIndex = 1:SensorSampleCount

        Latitude_deg = ...
            rad2deg(LatitudeSensor_rad(SampleIndex));

        Longitude_deg = ...
            rad2deg(LongitudeSensor_rad(SampleIndex));

        Altitude_km = ...
            AltitudeSensor_m(SampleIndex) / 1000;

        % World Magnetic Model.
        %
        % wrldmagm returns XYZ in NED coordinates in nT.
        MagneticFieldNED_nT = wrldmagm( ...
            Altitude_km, ...
            Latitude_deg, ...
            Longitude_deg, ...
            MagneticModelYear);

        MagneticFieldNED_nT = ...
            MagneticFieldNED_nT(:);

        if numel(MagneticFieldNED_nT) ~= 3

            error( ...
                'sensormodels:GenerateIdealMagnetometer:InvalidMagneticModelOutput', ...
                'wrldmagm did not return a three-component magnetic field.');
        end

        %% NED -> BODY using existing Block 2 transformations

        Roll_rad = EulerSensor_rad(SampleIndex,1);
        Pitch_rad = EulerSensor_rad(SampleIndex,2);
        Yaw_rad = EulerSensor_rad(SampleIndex,3);

        Quaternion = coordinates.Euler2Quaternion( ...
            Roll_rad, ...
            Pitch_rad, ...
            Yaw_rad);

        Cbn = coordinates.Quaternion2DCM(Quaternion);

        MagneticFieldBody_nT = ...
            Cbn.' * MagneticFieldNED_nT;

        %% nT -> uT

        MagneticFieldBody_uT(SampleIndex,:) = ...
            (MagneticFieldBody_nT ./ 1000).';

    end

    %% Build output

    Magnetometer = struct();

    Magnetometer.Time_s = SensorTime_s;

    Magnetometer.SampleRate_Hz = ...
        Timeline.SampleRate_Hz;

    Magnetometer.SampleCount = ...
        SensorSampleCount;

    Magnetometer.MagneticFieldBody_uT = ...
        MagneticFieldBody_uT;

    Magnetometer.Available = ...
        true(SensorSampleCount,1);

end